import { Typography } from '@mui/material'
import { useEffect, useState } from 'react'
import { formatDuration } from './conversation_duration'

interface ConversationTimerProps {
    completedAt: string | null
    startedAt: string
}

function elapsedMs(startedAt: string, completedAt: string | null) {
    const end = completedAt ? Date.parse(completedAt) : Date.now()

    return end - Date.parse(startedAt)
}

/**
 * Isolated run timer. While the run is active it ticks once a second; keeping it
 * in its own component means only this node re-renders, not the whole chat log.
 */
export function ConversationTimer({ completedAt, startedAt }: ConversationTimerProps) {
    const [, forceTick] = useState(0)

    useEffect(() => {
        if (completedAt) return

        const interval = setInterval(() => forceTick((tick) => tick + 1), 1000)

        return () => clearInterval(interval)
    }, [completedAt])

    // Derived during render so a completed run is static and a live run recomputes each tick.
    const elapsed = elapsedMs(startedAt, completedAt)

    return (
        <Typography aria-label="Elapsed time" color="text.secondary" variant="caption">
            {`â± ${formatDuration(elapsed)}`}
        </Typography>
    )
}

import { act, cleanup, render, screen } from '@testing-library/react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { formatDuration } from './conversation_duration'
import { ConversationTimer } from './conversation_timer'

describe('formatDuration', () => {
    it('formats sub-minute spans as m:ss', () => {
        expect(formatDuration(7_000)).toBe('0:07')
    })

    it('formats minute spans as m:ss', () => {
        expect(formatDuration(83_000)).toBe('1:23')
    })

    it('formats hour spans as h:mm:ss', () => {
        expect(formatDuration(3_753_000)).toBe('1:02:33')
    })

    it('clamps negative spans to zero', () => {
        expect(formatDuration(-5_000)).toBe('0:00')
    })
})

describe('ConversationTimer', () => {
    beforeEach(() => {
        vi.useFakeTimers()
        vi.setSystemTime(new Date('2026-01-01T00:00:05.000Z'))
    })

    afterEach(() => {
        cleanup()
        vi.useRealTimers()
    })

    it('freezes at the completed duration when the run is done', () => {
        render(
            <ConversationTimer completedAt="2026-01-01T00:01:30.000Z" startedAt="2026-01-01T00:00:00.000Z" />,
        )

        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('1:30')
    })

    it('ticks once a second while the run is active', () => {
        render(<ConversationTimer completedAt={null} startedAt="2026-01-01T00:00:00.000Z" />)

        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:05')

        act(() => {
            vi.advanceTimersByTime(3_000)
        })

        expect(screen.getByLabelText('Elapsed time')).toHaveTextContent('0:08')
    })
})

function padDurationPart(value: number) {
    return value.toString().padStart(2, '0')
}

/** Formats an elapsed millisecond span as `m:ss`, or `h:mm:ss` past an hour. */
export function formatDuration(ms: number) {
    const totalSeconds = Math.max(0, Math.floor(ms / 1000))
    const seconds = totalSeconds % 60
    const minutes = Math.floor(totalSeconds / 60) % 60
    const hours = Math.floor(totalSeconds / 3600)

    if (hours > 0) return `${hours}:${padDurationPart(minutes)}:${padDurationPart(seconds)}`

    return `${minutes}:${padDurationPart(seconds)}`
}

