import { Box, Stack, Typography } from '@mui/material'
import { useEffect, useLayoutEffect, useRef, type UIEvent } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import type { AgentConversation, AgentConversationEvent } from '../../data/data_types'
import { useAppTheme } from '../../theme/use_app_theme'
import type { PopupRunStatus } from './action_popup_defaults'
import { ActionConversationLink } from './action_conversation_link'
import { actionConversationUrlTransform } from './action_conversation_url_transform'
import { actionStatusLabel } from './action_status'
import { ConversationTimer } from './conversation_timer'
import { AgentToolEvent } from './agent_tool_event'
import { CommandExecutionEvent } from './command_execution_event'
import { ReasoningEvent } from './reasoning_event'
import { eventIdentity } from './event_display'

const CHAT_END_TOLERANCE = 4
const MIN_CHAT_HEIGHT = 96
const MARKDOWN_COMPONENTS = { a: ActionConversationLink }

interface ActionConversationChatProps {
    conversation: AgentConversation | null
    onConversationViewed?: (conversation: AgentConversation) => void
    status: PopupRunStatus
}

function viewportIsAtEnd(viewport: HTMLDivElement) {
    return viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop <= CHAT_END_TOLERANCE
}

function isCodexConversation(conversation: AgentConversation) {
    return conversation.providerSessions.some(({ agent }) => agent === 'codex')
        || conversation.entries.some((entry) => entry.kind === 'message' && entry.agent === 'codex')
        || conversation.entries.some((entry) => entry.kind === 'event' && !!entry.providerItemId)
}

function visibleConversationEntries(conversation: AgentConversation | null) {
    if (!conversation) return []
    const showEvents = isCodexConversation(conversation)

    return conversation.entries.filter((entry) => entry.kind === 'message'
        || (showEvents && (entry.type !== 'reasoning' || entry.status !== 'completed')))
}

function renderEvent(event: AgentConversationEvent) {
    if (event.type === 'reasoning') return <ReasoningEvent event={event} />
    if (event.type === 'commandExecution') return <CommandExecutionEvent event={event} />

    return <AgentToolEvent event={event} />
}

/** Ordered user/assistant transcript shown above the popup prompt. */
export function ActionConversationChat({ conversation, onConversationViewed, status }: ActionConversationChatProps) {
    const { markdownContentSx } = useAppTheme()
    const entries = visibleConversationEntries(conversation)
    const viewportRef = useRef<HTMLDivElement>(null)
    const conversationPathRef = useRef<string | null | undefined>(undefined)
    const stuckToEndRef = useRef(true)

    const handleScroll = (event: UIEvent<HTMLDivElement>) => {
        stuckToEndRef.current = viewportIsAtEnd(event.currentTarget)
    }

    useEffect(() => {
        if (!conversation?.completedAt || conversation.status === 'running' || conversation.status === 'waitingForInput') return

        onConversationViewed?.(conversation)
    }, [conversation, onConversationViewed])

    useLayoutEffect(() => {
        const viewport = viewportRef.current
        if (!viewport) return

        const conversationPath = conversation?.path ?? null
        const conversationChanged = conversationPathRef.current !== conversationPath
        conversationPathRef.current = conversationPath
        if (conversationChanged) stuckToEndRef.current = true
        if (!stuckToEndRef.current) return

        viewport.scrollTop = viewport.scrollHeight
    })

    return (
        <Stack
            aria-label="Conversation chat"
            onScroll={handleScroll}
            ref={viewportRef}
            spacing={1}
            sx={{ flex: 1, minHeight: MIN_CHAT_HEIGHT, overflowX: 'hidden', overflowY: 'auto' }}
        >
            {entries.map((entry) => entry.kind === 'message' ? (
                <Box
                    key={entry.id}
                    sx={{
                        alignSelf: entry.role === 'user' ? 'flex-end' : 'flex-start',
                        bgcolor: entry.role === 'user' ? 'custom.primaryBg' : 'custom.track',
                        borderRadius: 1,
                        flexShrink: 0,
                        maxWidth: '88%',
                        minWidth: 0,
                        overflowWrap: 'anywhere',
                        px: 1.25,
                        py: 1,
                        ...markdownContentSx,
                    }}
                >
                    <Box className="mdxeditor-content">
                        <ReactMarkdown
                            components={MARKDOWN_COMPONENTS}
                            remarkPlugins={[remarkGfm]}
                            urlTransform={actionConversationUrlTransform}
                        >
                            {entry.content}
                        </ReactMarkdown>
                    </Box>
                </Box>
            ) : (
                <Box key={eventIdentity(entry)} sx={{ minWidth: 0 }}>
                    {renderEvent(entry)}
                </Box>
            ))}
            {status !== 'idle' ? (
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', flexShrink: 0 }}>
                    <Typography color={status === 'failed' ? 'error.main' : 'text.secondary'} role="status" variant="caption">
                        {actionStatusLabel(status)}
                    </Typography>
                    {conversation ? (
                        <ConversationTimer completedAt={conversation.completedAt} startedAt={conversation.startedAt} />
                    ) : null}
                </Stack>
            ) : null}
        </Stack>
    )
}

import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../data/action_context'
import type { AgentConversation } from '../../data/data_types'
import { useActionRunSelector } from '../hooks/use_action_runs'
import { ActionConversationChat } from './action_conversation_chat'
import type { ActionConversationStore } from './action_conversation_store'

interface ActionConversationChatOwnerProps {
    actionId: string
    context: ActionContext
    onConversationViewed?: (conversation: AgentConversation) => void
    store: ActionConversationStore
}

/** Subscribes only chat boundary to selected and canonical live conversation changes. */
export function ActionConversationChatOwner(props: ActionConversationChatOwnerProps) {
    const { actionId, context, onConversationViewed, store } = props
    const liveConversation = useActionRunSelector(actionId, context, (run) => run?.conversation ?? null)
    const runStatus = useActionRunSelector(actionId, context, (run) => run?.status ?? 'idle')
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const conversation = liveConversation ?? selectedConversation
    const status = runStatus === 'idle' && conversation?.status === 'waitingForInput' ? 'waitingForInput' : runStatus

    return <ActionConversationChat conversation={conversation} onConversationViewed={onConversationViewed} status={status} />
}

import type { ActionFile } from './action_types'
import type { ActionSchedule } from './action_schedule_types'
import { DEFAULT_COLOR_SCHEME } from '../theme/theme_config'
import type { ProjectBackgroundShade } from '../theme/project_background_shade'
import { DEFAULT_CARD_SEPARATOR, type CardSeparator } from './card_identifiers'

export const DEFAULT_WORKING_FOLDER = 'active'
export const DEFAULT_ACTIONS_FOLDER = 'actions'
export const DEFAULT_ARCHIVED_FOLDER = 'archived'
export const DEFAULT_PROJECT_FOLDER = 'design'
export const DEFAULT_RELEASES_FOLDER = 'history'
export const DEFAULT_DIFF_COMMAND = 'git show {{commit}}'
export const AUTO_COMMIT_DELAY_MS = 30000

/** Card type id; projects can configure custom types beyond the default feature/job/bug. */
export type CardType = string
export type PushMode = 'auto' | 'manual'

export interface CardTypeConfig {
    color: string
    idPrefix: string
    label: string
    type: CardType
}

export interface StateConfig {
    alwaysVisible: boolean
    color?: string
    state: string
}

export interface ProjectConfig {
    actionsFolder: string
    archivedFolder: string
    backgroundShade: ProjectBackgroundShade
    cardBodyTemplate: string
    cardSeparator: CardSeparator
    cardTypes: CardTypeConfig[]
    diffCommand: string
    projectFolder: string
    pushMode: PushMode
    releasesFolder: string
    states: StateConfig[]
    workingFolder: string
}

/** How a file's `content` is encoded for the storage write path. Binary assets use base64. */
export type FileEncoding = 'utf-8' | 'base64'

export interface MarkdownFile {
    content: string
    encoding?: FileEncoding
    path: string
    sha?: string
}

export interface ProjectAsset {
    content: string
    contentType: string
    encoding: 'base64'
    path: string
}

export interface CardHeader {
    affects: string[]
    after: string | null
    /** Terminal conversation references inside activity files; the name mirrors the persisted `agents` field. */
    agentLogReferences: string[]
    author: string | null
    id: string
    internalId: string | null
    owner: string | null
    policy: Record<string, boolean>
    status: string | null
    title: string
    worktree?: number | null
    worktreeError?: string | null
    worktreeValue?: string | null
}

export interface ProjectCard {
    agentConversationErrors: AgentConversationError[]
    agentConversations: AgentConversation[]
    content: string
    header: CardHeader
    /** Raw frontmatter fields as written in the file, including unknown keys. */
    headerFields: Record<string, string | string[] | Record<string, string>>
    isActive: boolean
    path: string
    sha?: string
}

export interface ProjectSnapshot {
    activeCards: ProjectCard[]
    backgroundCards: ProjectCard[]
    repositoryFiles: string[]
    workingFolder: string
}

export interface CardDraft {
    body: string
    bodyIncludesTemplate?: boolean
    title: string
    type: CardType
}

export interface ProjectReference {
    branch: string
    id: string
    owner?: string
    repository?: string
    rootPath?: string
}

export interface WorktreeRecord {
    branch: string | null
    error: string | null
    parkingBranch: string
    path: string
    status: WorktreeStatus
    valid: boolean
}

export interface WorktreeState {
    error: string | null
    primaryStatus: WorktreeStatus | null
    project: ProjectReference | null
    records: WorktreeRecord[]
}

export interface WorktreeStatus {
    /** Commits on the worktree branch that the configured upstream lacks; 0 when there is no upstream. */
    ahead: number
    /** Commits on the worktree branch that the project branch lacks. */
    baseAhead: number
    /** Commits on the project branch that the worktree branch lacks; cleared by rebasing. */
    baseBehind: number
    /** Commits on the configured upstream that the worktree branch lacks; 0 when there is no upstream. */
    behind: number
    dirty: boolean
    hasUpstream: boolean
}

export interface PrepareWorktreeRequest {
    branchName: string
    project: ProjectReference
    worktree: number
}

export interface WorktreeOperationRequest {
    project: ProjectReference
    worktree: number
}

export interface CardWorktreeIntegrationRequest extends WorktreeOperationRequest {
    cardInternalId: string
    projectFolder: string
}

export type IntegrateWorktreeRequest = CardWorktreeIntegrationRequest | WorktreeOperationRequest

export interface CommitWorktreeRequest extends WorktreeOperationRequest {
    message: string
}

export interface RepositoryReference extends ProjectReference {
    owner: string
    repository: string
}

export interface BranchReference {
    name: string
}

export interface TopLevelFolderReference {
    name: string
    path: string
}

export const MISSING_WORKING_FOLDER_ERROR = 'missing-working-folder'

export class MissingWorkingFolderError extends Error {
    code: typeof MISSING_WORKING_FOLDER_ERROR
    workingFolder: string

    constructor(workingFolder: string) {
        super(`Working folder is missing: ${workingFolder}`)
        this.code = MISSING_WORKING_FOLDER_ERROR
        this.workingFolder = workingFolder
    }
}

export interface CommitRequest {
    branch: string
    files: MarkdownFile[]
    message: string
    moves?: MoveFile[]
}

export type CommitResult = MarkdownFile[]

export interface MoveFile {
    content: string
    encoding?: FileEncoding
    fromPath: string
    sha?: string
    toPath: string
}

export interface MoveFilesRequest {
    branch: string
    message: string
    moves: MoveFile[]
}

export interface DeleteFileRequest {
    branch: string
    message: string
    path: string
    sha?: string
}

export interface DeleteFolderRequest {
    branch: string
    message: string
    path: string
}

export type ProjectWatchChangeKind = 'added' | 'changed' | 'removed' | 'unknown'

export interface ProjectWatchEvent {
    changeKind: ProjectWatchChangeKind
    path: string
}

/** A background agent/action currently running against a card or file. */
export interface RunningAgent {
    id: string
    label: string
}

export type AgentConversationStatus = 'cancelled' | 'completed' | 'failed' | 'running' | 'waitingForInput'
export type AgentMessageRole = 'assistant' | 'user'

export interface AgentConversationMessage {
    agent?: string
    content: string
    id: string
    role: AgentMessageRole
    sequence?: number
    timestamp: string
}

export interface AgentProviderSession {
    agent: string
    conversationId: string
    createdAt: string
    lastUsedAt: string
    synchronizedThroughMessageId: string
}

export interface AgentConversationEvent {
    command?: string
    content: string
    details?: string[]
    durationMs?: number
    exitCode?: number
    id: string
    label?: string
    output?: string
    providerItemId?: string
    sequence?: number
    status?: string
    summary?: string[]
    timestamp: string
    type: string
    workingDirectory?: string
}

export interface AgentConversationMessageEntry extends AgentConversationMessage {
    kind: 'message'
}

export interface AgentConversationEventEntry extends AgentConversationEvent {
    kind: 'event'
}

export type AgentConversationEntry = AgentConversationMessageEntry | AgentConversationEventEntry

export interface AgentTokenUsage {
    cachedInputTokens: number
    costUsd?: number
    inputTokens: number
    outputTokens: number
    reasoningTokens: number
    totalTokens: number
}

export interface AgentConversation {
    actionId?: string | null
    cardInternalId?: string | null
    cardPath: string | null
    completedAt: string | null
    entries: AgentConversationEntry[]
    hasExplicitTitle: boolean
    id: string
    path: string
    providerSessions: AgentProviderSession[]
    startedAt: string
    status: AgentConversationStatus
    title: string
    usage?: AgentTokenUsage
}

export interface AgentConversationError {
    message: string
    path: string
}

export type AgentRunEvent =
    | {
        conversation: AgentConversation
        runId: string
        type: 'started'
    }
    | {
        event: AgentConversationEventEntry
        runId: string
        type: 'agentEvent'
    }
    | {
        content: string
        runId: string
        type: 'error' | 'output'
    }
    | {
        conversation: AgentConversation
        runId: string
        type: 'closed'
    }

export interface StorageProjectFiles {
    files: MarkdownFile[]
    workingFolder: string
}

export interface StorageService {
    addWorktree?(project: ProjectReference): Promise<boolean>
    checkoutBranch(project: ProjectReference, branch: string): Promise<ProjectReference>
    commit(request: CommitRequest): Promise<CommitResult>
    commitWorktree?(request: CommitWorktreeRequest): Promise<void>
    createProject(project: ProjectReference, workingFolder: string): Promise<ProjectReference>
    deleteFile(request: DeleteFileRequest): Promise<void>
    deleteFolder(request: DeleteFolderRequest): Promise<void>
    discardWorktreeChanges?(request: WorktreeOperationRequest): Promise<void>
    discardPendingCommits?(project: ProjectReference): void
    hasPendingPush?(project: ProjectReference): boolean
    listBranches(project: ProjectReference): Promise<BranchReference[]>
    listAgentConversationReferences?(project: ProjectReference, projectFolder: string): Promise<string[]>
    listRepositories(): Promise<RepositoryReference[]>
    loadActionFiles(project: ProjectReference, actionsFolder: string): Promise<ActionFile[]>
    loadActionSchedules?(project: ProjectReference, actionsFolder: string): Promise<ActionSchedule[]>
    cancelActionSchedule?(project: ProjectReference, actionsFolder: string, scheduleId: string): Promise<ActionSchedule[]>
    loadAgentConversation?(project: ProjectReference, path: string): Promise<AgentConversation>
    loadProjectAsset?(project: ProjectReference, path: string): Promise<ProjectAsset>
    loadProject(project: ProjectReference, workingFolder: string): Promise<StorageProjectFiles>
    loadFile?(project: ProjectReference, path: string): Promise<MarkdownFile>
    loadProjectRoot(project: ProjectReference, workingFolder: string): Promise<StorageProjectFiles>
    loadProjectConfig(project: ProjectReference): Promise<Partial<ProjectConfig> | null>
    onWorktreesChanged?(callback: (state: WorktreeState) => void): () => void
    restorePendingCommits?(project: ProjectReference): Promise<void>
    resolveProject?(project: ProjectReference): Promise<ProjectReference>
    listRepositoryFiles(project: ProjectReference): Promise<string[]>
    listTopLevelFolders(project: ProjectReference): Promise<TopLevelFolderReference[]>
    loadPendingPush?(project: ProjectReference): Promise<void>
    integrateWorktree?(request: IntegrateWorktreeRequest): Promise<void>
    moveFiles(request: MoveFilesRequest): Promise<void>
    parkWorktree?(request: WorktreeOperationRequest): Promise<void>
    prepareWorktree?(request: PrepareWorktreeRequest): Promise<void>
